let lang='fr',mode='zfc',frame=0,timer=null,curves=[],cfg={},state={};
const $=id=>document.getElementById(id),t=(fr,en)=>lang==='fr'?fr:en;
const names={zfc:['ZFC / FC','ZFC / FC'],mh:['Cycle M(H)','M(H) loop'],initial:['Première aimantation','Initial magnetization'],rem:['IRM / DCD / ΔM','IRM / DCD / ΔM'],time:['Relaxation IRM(t) / DCD(t)','IRM(t) / DCD(t) relaxation'],forc:['FORC','FORC']};
const cols=['#087c83','#c3613d','#7355a2','#527a2a'];
function link(url,label){return `<a href="${url}" target="_blank" rel="noopener noreferrer" title="${t('Nouvel onglet','New tab')}">${label}</a>`;}
function range(id,label,min,max,value,step,unit){return `<label for="${id}">${label}<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><output id="${id}Val">${value} ${unit}</output></label>`;}
function render(){if(mode!=='forc')mode='forc';stop();document.documentElement.lang=lang;document.title=t('NanoBioMat — Magnétisme interactif','NanoBioMat — Interactive magnetism');$('nav').setAttribute('aria-label',t('Explorations','Explorations'));$('lang').textContent=lang==='fr'?'EN':'FR';$('lang').setAttribute('aria-label',t('Switch to English','Passer en français'));$('strap').textContent=t('Nanomagnétisme · Bases théoriques','Nanomagnetism · Theoretical background');$('badge').textContent=t('Bases théoriques','Theoretical background');$('title').textContent=t('Du moment magnétique à la courbe mesurée','From magnetic moments to measured curves');$('intro').textContent=t('Explorer ce que mesurent les protocoles, comment l’anisotropie et la taille interviennent, et où commencent les limites d’un modèle.','Explore what each protocol measures, how anisotropy and size matter, and where a model reaches its limits.');$('nav').innerHTML=Object.entries(names).filter(([k])=>['forc'].includes(k)).map(([id,n])=>`<button data-mode="${id}" aria-pressed="${id===mode}">${n[lang==='fr'?0:1]}</button>`).join('');$('nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});
let controls='',explain='',model='',title='';
const shared=range('K','Keff',5,40,20,1,'kJ/m³')+range('d',t('Diamètre médian','Median diameter'),8,24,16,1,'nm')+range('sigma',t('Dispersion σln(d)','Size width σln(d)'),0,.4,.12,.02,'');
if(mode==='zfc'){title=t('Le blocage dépend du temps de mesure','Blocking depends on measurement time');controls=`<label for="protocol">${t('Protocole animé','Animated protocol')}<select id="protocol"><option value="z">ZFC · ${t('réchauffement','warming')}</option><option value="f">FC · ${t('refroidissement','cooling')}</option></select></label>`+shared+range('seconds',t('Temps par kelvin','Time per kelvin'),1,20,2,1,'s/K');explain=t('En ZFC, l’échantillon refroidit sans champ. Un faible champ est ensuite appliqué à basse température. L’aimantation est mesurée au réchauffement. En FC, le refroidissement et la mesure se déroulent sous ce champ. Au-dessus du domaine de blocage, les moments relaxent rapidement. Le faible champ ne les aligne pas tous.','For ZFC, the sample cools in zero field. A weak field is then applied at low temperature. Magnetization is measured on warming. For FC, cooling and measurement occur in this field. Above the blocking range, moments relax rapidly. The weak field does not align them all.');model=t('Chaque flèche représente le moment résultant d’une nanoparticule. Elle ne représente pas un spin atomique. L’ordre ferrimagnétique interne persiste dans le régime superparamagnétique. Le maximum ZFC et la séparation ZFC/FC donnent des repères différents. Aucun ne fournit une mesure universelle de TB.','Each arrow represents a nanoparticle’s net moment. It does not represent an atomic spin. Internal ferrimagnetic order persists in the superparamagnetic regime. The ZFC maximum and ZFC/FC separation provide different markers. Neither gives a universal measure of TB.');}
if(mode==='mh'){title=t('Rotation cohérente et hystérésis','Coherent rotation and hysteresis');controls=`<label for="axes">${t('Axes faciles','Easy axes')}<select id="axes"><option value="random">${t('Aléatoires en 3D','Random in 3D')}</option><option value="aligned">${t('Parallèles au champ','Parallel to the field')}</option></select></label>`;explain=t('Le champ passe d’une forte valeur positive à une forte valeur négative. Il remonte ensuite. Le moment reste dans un minimum local d’énergie jusqu’à sa disparition.','The field moves from a large positive value to a large negative value. It then increases again. The moment remains in a local energy minimum until that minimum disappears.');model=t('Le modèle de Stoner–Wohlfarth suppose des particules monodomaines et une anisotropie uniaxiale. Les moments tournent de façon cohérente. Le calcul omet les interactions et l’activation thermique (T = 0). Des axes uniformément distribués en 3D donnent MR/MS = ⟨|cos θ|⟩ = 0,5. Des axes parallèles donnent 1. Ces résultats dépendent des hypothèses du modèle.','The Stoner–Wohlfarth model assumes single-domain particles and uniaxial anisotropy. Moments rotate coherently. The calculation omits interactions and thermal activation (T = 0). Uniformly distributed 3D axes give MR/MS = ⟨|cos θ|⟩ = 0.5. Parallel axes give 1. These results depend on the model assumptions.');}
if(mode==='initial'){title=t('Comment se construit la première aimantation ?','How does initial magnetization develop?');controls=shared+range('T',t('Température','Temperature'),20,300,100,10,'K')+range('rate',t('Vitesse de balayage','Sweep rate'),.1,5,1,.1,'mT/s');explain=t('Le champ augmente depuis un état démagnétisé. Le champ réduit la barrière KV. Cette barrière et le temps disponible déterminent les probabilités de retournement. K et V ont des effets distincts. La distribution des tailles élargit celle des barrières. Les grands moments contribuent davantage à l’aimantation.','The field increases from a demagnetized state. The field lowers the KV barrier. This barrier and the available time determine switching probabilities. K and V have different effects. The size distribution broadens the barrier distribution. Larger moments contribute more to magnetization.');model=t('Le modèle utilise deux minima du paysage de Stoner–Wohlfarth. Il décrit les transitions de Néel et la rotation dans chaque minimum. Il omet les fluctuations dans les puits. Sa fiabilité diminue lorsque KV/kBT est faible. Il ne décrit pas une courbe de Langevin exacte. Il ne réalise aucun ajustement expérimental.','The model uses two minima of the Stoner–Wohlfarth landscape. It describes Néel transitions and rotation within each minimum. It omits intrawell fluctuations. Its reliability decreases when KV/kBT is small. It does not describe an exact Langevin curve. It performs no experimental fit.');}
if(mode==='rem'){title=t('Rémanence et relation de Wohlfarth','Remanence and the Wohlfarth relation');controls=range('width',t('Largeur des champs de retournement','Switching-field width'),5,25,12,1,'% H₀')+`<label for="view">${t('Représentation','View')}<select id="view"><option value="field">IRM(H), DCD(H), ΔM(H)</option><option value="henkel">${t('Diagramme de Henkel','Henkel plot')}</option></select></label>`;explain=t('Le protocole IRM part d’un état démagnétisé. Un champ est appliqué puis retiré. La rémanence est mesurée à champ nul. Le protocole DCD part d’une saturation positive. Un champ inverse est appliqué puis retiré. La rémanence est également mesurée à champ nul. H désigne le champ appliqué auparavant.','The IRM protocol starts from a demagnetized state. A field is applied and removed. Remanence is measured in zero field. The DCD protocol starts from positive saturation. A reverse field is applied and removed. Remanence is also measured in zero field. H denotes the previously applied field.');model=t('Le modèle utilise des éléments bistables symétriques indépendants. Leurs champs de retournement suivent une distribution gaussienne tronquée. Les rémanences IRM et DCD sont normalisées par la rémanence à saturation. Un ΔM négatif suggère une tendance démagnétisante. Un ΔM positif suggère une tendance magnétisante. Le signe ne prouve pas la nature dipolaire ou d’échange des interactions.','The model uses independent symmetric bistable elements. Their switching fields follow a truncated Gaussian distribution. IRM and DCD remanences are normalized by saturation remanence. Negative ΔM suggests a demagnetizing tendency. Positive ΔM suggests a magnetizing tendency. The sign does not establish dipolar or exchange interactions.');}
if(mode==='time'){title=t('Après le retrait du champ : la relaxation','After removing the field: relaxation');controls=shared+range('T',t('Température','Temperature'),20,300,100,10,'K')+range('hp',t('Champ de préparation |H|/HK','Preparation field |H|/HK'),.1,1.1,.5,.1,'');explain=t('La préparation IRM part d’un état démagnétisé. La préparation DCD part d’une saturation positive suivie d’un champ inverse. Le champ revient ensuite à zéro. L’aimantation évolue avec le temps. Ces traces temporelles diffèrent des courbes IRM(H) et DCD(H).','IRM preparation starts from a demagnetized state. DCD preparation starts from positive saturation followed by a reverse field. The field then returns to zero. Magnetization evolves with time. These time traces differ from IRM(H) and DCD(H) curves.');model=t('Le calcul utilise l’approximation à deux états de la première aimantation. Chaque pas de préparation dure 0,1 s. L’IRM comporte 61 pas par branche. La DCD comporte 121 puis 61 pas. Le temps commence après le retrait complet du champ. L’ordonnée représente M/MS. Elle ne normalise pas chaque trace par sa valeur initiale. La relation de Wohlfarth ne s’applique pas point par point à ces traces.','The calculation uses the two-state approximation for initial magnetization. Each preparation step lasts 0.1 s. IRM uses 61 steps per branch. DCD uses 121 then 61 steps. Time starts after complete field removal. The ordinate represents M/MS. It does not normalize each trace by its initial value. The Wohlfarth relation does not apply point by point to these traces.');}
if(mode==='forc'){title=t('Du protocole FORC à une distribution','From a FORC protocol to a distribution');controls=range('sc',t('Dispersion des coercivités','Coercivity spread'),.05,.25,.12,.01,'H₀')+range('su',t('Dispersion des champs de biais','Bias-field spread'),.03,.25,.08,.01,'H₀')+range('hr',t('Champ de retournement Hr','Reversal field Hr'),-1.2,.2,-.6,.05,'H₀');explain=t('Chaque courbe part de la saturation positive. Le champ descend jusqu’à Hr, puis remonte. Plusieurs valeurs de Hr produisent une famille de courbes. Une dérivée mixte définit la distribution FORC. Hr est le champ de retournement. Hc = (H − Hr)/2 est une coordonnée de coercivité ; Hu = (H + Hr)/2 est une coordonnée de biais. ρ mesure la variation de pente entre courbes voisines. Hc ne désigne pas ici la coercivité globale d’un cycle.','Each curve starts from positive saturation. The field decreases to Hr and then increases. Multiple Hr values produce a curve family. A mixed derivative defines the FORC distribution. Hr is the reversal field. Hc = (H − Hr)/2 is a coercivity coordinate; Hu = (H + Hr)/2 is a bias coordinate. ρ measures slope changes between neighbouring curves. Hc does not denote the overall loop coercivity here.');model=t('Le modèle de Preisach utilise des hystérons rectangulaires indépendants. La carte affiche la densité théorique qui génère les courbes. Elle ne dérive pas des données bruitées. Une largeur selon Hu ne détermine pas à elle seule les interactions. Le modèle omet la réponse réversible et les effets thermiques.','The Preisach model uses independent rectangular hysterons. The map displays the theoretical density that generates the curves. It does not derive from noisy data. A spread along Hu does not uniquely determine interactions. The model omits reversible response and thermal effects.');}
$('app').innerHTML=`<div class="layout"><section class="panel"><h2>${title}</h2><div id="legend" class="key"></div><div id="graph"></div><div class="playrow"><button id="play">${t('Animer','Play')}</button><button id="reset">${t('Recommencer','Restart')}</button><input id="timeline" type="range" min="0" max="100" value="0" aria-label="${t('Progression de l’animation','Animation progress')}"><button id="csv">CSV</button></div><div id="readout" class="readout"></div><div id="moments"></div><p class="note" id="momentnote"></p><p>${explain}</p></section><aside class="panel controls">${controls}<p class="note" id="parameters"></p></aside></div><details open><summary>${t('Protocole et coordonnées','Protocol and coordinates')}</summary><p>${model}</p><div class="math" id="equation"></div><p class="note" id="limits"></p></details>`;
$('app').querySelectorAll('.controls input,.controls select').forEach(x=>x.addEventListener('input',()=>{if(x.tagName==='INPUT')$(x.id+'Val').textContent=x.value+' '+({K:'kJ/m³',d:'nm',T:'K',rate:'mT/s',seconds:'s/K',sc:'H₀',su:'H₀',hr:'H₀',width:'% H₀'}[x.id]||'');stop();compute();}));$('play').onclick=()=>timer?stop():play();$('reset').onclick=()=>{stop();frame=0;draw();};$('timeline').oninput=()=>{stop();frame=Math.round(+$('timeline').value/100*(state.n-1));draw();};$('csv').onclick=exportCSV;resources();compute();}
function val(id,fallback){return $(id)?+$(id).value:fallback;}
function compute(){cfg={K:val('K',20)*1000,d:val('d',16),sigma:val('sigma',.12),T:val('T',100)};cfg.Bk=2*cfg.K/MS;cfg.V=Math.PI/6*(cfg.d*1e-9)**3;frame=0;state={};
if(mode==='zfc'){state.data=zfcfc(cfg.K,cfg.d,cfg.sigma,val('seconds',2));curves=[{name:'ZFC',data:state.data.z},{name:'FC',data:state.data.f}];state.selected=$('protocol').value==='z'?state.data.z:state.data.f;state.n=state.selected.length;state.xlim=[0,400];state.ylim=[0,Math.max(...curves.flatMap(c=>c.data.map(p=>p.y)))*1.12];state.xlabel='T (K)';state.ylabel='M / Ms';state.eq='τN = τ₀ exp(Keff V / kBT) ;  TB* = Keff V / [kB ln(tm / τ₀)]';state.extra=t('TB* donne un repère monodisperse à champ nul pour tm = 100 s. Le calcul suit une rampe en température. La FC commence à l’équilibre à 400 K. Les plus fortes barrières peuvent empêcher cet équilibre. Le calcul reprend l’approximation à deux minima de la première aimantation. Il omet les fluctuations intrapuits et la rotation brownienne.','TB* gives a monodisperse zero-field marker for tm = 100 s. The calculation follows a temperature ramp. FC starts at equilibrium at 400 K. The largest barriers may prevent this equilibrium. The calculation uses the two-minimum approximation for initial magnetization. It omits intrawell fluctuations and Brownian rotation.');}
if(mode==='mh'){let path=[...seq(1.2,-1.2,241),...seq(-1.2,1.2,241)];if($('axes').value==='aligned'){let m=1;state.loop=path.map(h=>{if(h<=-1)m=-1;if(h>=1)m=1;return{x:h,y:m,p:Array(32).fill((m+1)/2)};});}else state.loop=runSW(path,{...cfg,T:0,dt:1},1);curves=[{name:t('Cycle idéal T = 0','Ideal loop T = 0'),data:state.loop}];state.n=state.loop.length;state.selected=state.loop;state.xlim=[-1.25,1.25];state.ylim=[-1.1,1.1];state.xlabel='H / HK';state.ylabel='M / Ms';state.eq='E(φ) / KV = sin²(φ − θ) − 2h cos φ ;  h = H/HK ;  μ₀HK = 2Keff/Ms';state.extra=t('32 orientations, uniformes en cos θ. Calcul des minima d’énergie, résolution en champ Δh = 0,01.','32 orientations, uniform in cos θ. Energy minima calculated on a field grid Δh = 0.01.');}
if(mode==='initial'){const hs=seq(0,1.2,121);cfg.dt=cfg.Bk*.01/(val('rate',1)/1000);state.selected=runSW(hs,cfg,.5).map(p=>({...p,h:p.x,x:p.x*cfg.Bk*1000}));curves=[{name:t('Première aimantation','Initial magnetization'),data:state.selected}];state.n=121;state.xlim=[0,cfg.Bk*1200];state.ylim=[0,1.05];state.xlabel='μ₀H (mT)';state.ylabel='M / Ms';state.eq='μ = Ms V ;  Γ± = (2τ₀)⁻¹ exp(−ΔE±/kBT)';state.extra=t('Les courbes utilisent une distribution lognormale en nombre, pondérée par le volume pour calculer M/Ms.','A number-weighted lognormal size distribution is volume-weighted to calculate M/Ms.');}
if(mode==='rem'){let d=remanence(val('width',12));state.data=d;state.n=d.length;if($('view').value==='henkel'){curves=[{name:'Wohlfarth',data:d.map(p=>({x:p.irm,y:p.dcd}))}];state.xlim=[0,1];state.ylim=[-1.1,1.1];state.xlabel='mIRM';state.ylabel='mDCD';}else{curves=['irm','dcd','delta'].map((k,i)=>({name:['mIRM','mDCD','ΔM'][i],data:d.map(p=>({x:p.x,y:p[k]}))}));state.xlim=[0,1.2];state.ylim=[-1.1,1.1];state.xlabel='|H| / H₀';state.ylabel=t('Rémanence normalisée','Normalized remanence');}state.selected=curves[0].data;state.eq='ΔM(H) = mDCD(H) − [1 − 2mIRM(H)] ;  ΔM = 0';state.extra=t('Référence sans interactions uniquement. Le diagramme de Henkel montre mDCD en fonction de mIRM ; ΔM montre l’écart à cette référence en fonction de H.','Noninteracting reference only. A Henkel plot shows mDCD versus mIRM; ΔM shows deviation from this reference versus H.');}
if(mode==='time'){let d=remTime(cfg.K,cfg.d,cfg.sigma,cfg.T,val('hp',.5));curves=[{name:'IRM(t)',data:d.irm},{name:'DCD(t)',data:d.dcd}];state.selected=d.irm;state.n=d.irm.length;state.xlim=[-6,5];state.ylim=[-.55,.55];state.xlabel='log₁₀(t / s)';state.ylabel='M / Ms';state.eq='M(t) = Σi μi ⟨cos θi⟩₀ exp(−t/τi) ;  τi = τ₀ exp(Keff Vi/kBT)';state.extra=t('À champ nul, chaque population préparée relaxe vers un moment moyen nul. Les amplitudes et même le signe dépendent de la préparation.','At zero field each prepared population relaxes toward zero mean moment. Amplitudes, and even the sign, depend on preparation.');}
if(mode==='forc'){let a=forcEnsemble(val('sc',.12),val('su',.08)),hr=val('hr',-.6);state.a=a;state.hr=hr;curves=seq(-1.2,.2,15).map(h=>({name:'Hr = '+h.toFixed(2),data:seq(h,1.5,100).map(x=>({x,y:forcM(a,h,x)}))}));let descend=seq(1.5,hr,80).map(x=>({x,y:forcM(a,x,x),stage:0}));state.selected=[...descend,...seq(hr,1.5,160).map(x=>({x,y:forcM(a,hr,x),stage:1}))];state.n=state.selected.length;state.xlim=[-1.5,1.5];state.ylim=[-1.1,1.1];state.xlabel='H / H₀';state.ylabel='M / Ms';state.eq='ρ(H, Hr) = −½ ∂²(M/Ms)/∂H∂Hr ;  Hc = (H − Hr)/2 ;  Hu = (H + Hr)/2';state.extra=t('H₀ est une échelle arbitraire. Couleur : densité théorique relative (maximum = 1), pas une mesure expérimentale.','H₀ is an arbitrary scale. Colour: relative theoretical density (maximum = 1), not experimental data.');}
$('legend').innerHTML=(mode==='forc'?[{name:t('Famille FORC','FORC family')},{name:t('Protocole sélectionné','Selected protocol')}]:curves).map((c,i)=>`<span style="--color:${cols[i]}">${c.name}</span>`).join('');$('equation').textContent=state.eq;$('limits').textContent='';$('limits').hidden=true;
let alpha=cfg.K*cfg.V/(KB*cfg.T),low=sizes(cfg.d,cfg.sigma).filter(s=>cfg.K*s.v/(KB*cfg.T)<5).reduce((a,s)=>a+s.w,0);$('parameters').innerHTML=['zfc','initial','time'].includes(mode)?`Ms = 480 kA/m · τ₀ = 10⁻⁹ s<br>V₅₀ = ${(cfg.V*1e27).toFixed(0)} nm³<br>μ₀HK = ${(cfg.Bk*1000).toFixed(1)} mT<br>`+(mode==='zfc'?`${t('Champ appliqué','Applied field')} = ${(cfg.Bk*.02*1000).toFixed(2)} mT<br>TB* = ${(cfg.K*cfg.V/(KB*Math.log(100/TAU0))).toFixed(0)} K`:`KV₅₀/kBT = ${alpha.toFixed(1)}<br>${t('Fraction du moment avec KV/kBT < 5','Moment fraction with KV/kBT < 5')} : ${(100*low).toFixed(0)} %`)+`<br><br>${t('Paramètres illustratifs, pas une caractérisation de l’échantillon. Anisotropie uniaxiale effective positive ; ce K n’est pas le K₁ cubique de la magnétite.','Illustrative parameters, not a sample characterization. Positive effective uniaxial anisotropy; this K is not magnetite’s cubic K₁.')}`:t('Les modèles sont volontairement idéalisés pour rendre le mécanisme lisible.','The models are deliberately idealized to make the mechanism understandable.');draw();}
function plot(curves,xlim,ylim,xlabel,ylabel,point,extras=''){let W=720,H=350,l=70,r=18,top=24,b=54;const X=x=>l+(x-xlim[0])/(xlim[1]-xlim[0])*(W-l-r),Y=y=>H-b-(y-ylim[0])/(ylim[1]-ylim[0])*(H-top-b);let s=`<svg class="plot" role="img" aria-label="${xlabel}, ${ylabel}" viewBox="0 0 ${W} ${H}"><defs><clipPath id="area"><rect x="${l}" y="${top}" width="${W-l-r}" height="${H-top-b}"/></clipPath></defs>`;for(let i=0;i<=4;i++){let x=xlim[0]+i/4*(xlim[1]-xlim[0]),y=ylim[0]+i/4*(ylim[1]-ylim[0]);s+=`<path d="M${X(x)},${top}V${H-b} M${l},${Y(y)}H${W-r}" stroke="#e7eeeb" fill="none"/><text x="${X(x)}" y="${H-b+22}" text-anchor="middle">${Number(x.toFixed(2))}</text><text x="${l-10}" y="${Y(y)+4}" text-anchor="end">${Number(y.toFixed(2))}</text>`;}if(ylim[0]<0)s+=`<path d="M${l},${Y(0)}H${W-r}" stroke="#b6c9c4"/>`;s+=`<text x="${l}" y="16">${ylabel}</text><text x="${W-r}" y="${H-6}" text-anchor="end">${xlabel}</text><g clip-path="url(#area)">`;curves.forEach((c,i)=>{let path=c.data.map((p,j)=>(j?'L':'M')+X(p.x).toFixed(2)+','+Y(p.y).toFixed(2)).join(' ');s+=`<path d="${path}" fill="none" stroke="${c.color||cols[i%4]}" stroke-width="${c.width||2.5}" opacity="${c.opacity||1}"/>`;});if(point)s+=`<circle cx="${X(point.x)}" cy="${Y(point.y)}" r="6" fill="#c3613d" stroke="white" stroke-width="2"/>`;return s+'</g>'+extras+'</svg>';}
function moments(p,h,T=0){let s=`<svg class="plot smallplot" viewBox="0 0 720 155" role="img" aria-label="${t('Moments résultants des nanoparticules','Net nanoparticle moments')}"><defs><radialGradient id="sphere" cx="30%" cy="25%"><stop stop-color="#fff"/><stop offset="1" stop-color="#c8ded8"/></radialGradient><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0,0L5,2.5L0,5" fill="#087c83"/></marker></defs>`;for(let j=0;j<24;j++){let i=Math.floor(j*32/24),x=38+j%12*58,y=45+Math.floor(j/12)*62,r=landscape(h,i),prob=p?.[i]??.5;let threshold=(Math.sin((j+1)*123.45+(T>0?frame*.72:0))*43758.54)%1;threshold=Math.abs(threshold);let phi=r[0]===1?r[3]:(threshold<prob?r[3]:r[4]);if(mode==='mh'&&$('axes').value==='aligned')phi=prob>.5?0:Math.PI;let dx=Math.cos(phi)*17,dy=Math.sin(phi)*17*(j%2?1:-1);s+=`<circle cx="${x}" cy="${y}" r="24" fill="url(#sphere)"/><line x1="${x-dx*.6}" y1="${y-dy*.6}" x2="${x+dx}" y2="${y+dy}" stroke="#087c83" stroke-width="2.4" marker-end="url(#arrow)"/>`;}return s+`<text x="20" y="151">${t('Champ','Field')} : ${h>=0?'→':'←'} · ${t('un moment résultant par sphère','one net moment per sphere')}</text></svg>`;}
function heatmap(){let sc=val('sc',.12),su=val('su',.08),s=`<svg class="plot" viewBox="0 0 720 290" role="img" aria-label="${t('Densité FORC théorique','Theoretical FORC density')}">`;for(let i=0;i<50;i++)for(let j=0;j<40;j++){let c=(i+.5)/50*1.1,u=-.5+(j+.5)/40,v=Math.exp(-.5*((c-.45)/sc)**2-.5*(u/su)**2);s+=`<rect x="${70+i*12.2}" y="${20+(39-j)*5.5}" width="12.4" height="5.7" fill="rgb(${Math.round(246-238*v)},${Math.round(248-124*v)},${Math.round(245-114*v)})"/>`;}s+=`<text x="70" y="14">Hu / H₀</text><text x="60" y="28" text-anchor="end">0.5</text><text x="60" y="134" text-anchor="end">0</text><text x="60" y="240" text-anchor="end">−0.5</text><text x="70" y="260">0</text><text x="680" y="260" text-anchor="end">1.1 · Hc / H₀</text><text x="70" y="285">${t('Clair : 0 · foncé : maximum de densité','Light: 0 · dark: maximum density')}</text></svg>`;return s;}
function draw(){let p=state.selected[Math.min(frame,state.n-1)],shown=curves.map((c,i)=>({...c,opacity:.25}));if(mode==='forc'){shown=curves.map(c=>({...c,color:cols[0],width:1,opacity:.25}));shown.push({color:cols[1],data:state.selected.slice(0,frame+1),width:3});}else if(mode==='zfc'){shown.push({data:state.selected.slice(0,frame+1),color:$('protocol').value==='z'?cols[0]:cols[1],width:3});}else shown=[...shown,...curves.map((c,i)=>({...c,color:cols[i%4],data:c.data.slice(0,frame+1)}))];$('graph').innerHTML=plot(shown,state.xlim,state.ylim,state.xlabel,state.ylabel,p);$('timeline').value=frame/(state.n-1)*100;
let text='';if(mode==='zfc'){let tb=cfg.K*cfg.V/(KB*Math.log(100/TAU0));text=`T = ${p.x.toFixed(1)} K · M/Ms = ${p.y.toFixed(4)} · `+t('repère médian : ','median guide: ')+(p.x<tb?t('moment bloqué à 100 s','blocked on 100 s'):t('relaxation rapide à 100 s','fast relaxation on 100 s'));$('moments').innerHTML=moments(p.p,.02,p.x>tb?p.x:0);}
else if(mode==='mh'){text=`H/HK = ${p.x.toFixed(2)} · M/Ms = ${p.y.toFixed(3)} · `+t('rémanence idéale : ','ideal remanence: ')+($('axes').value==='random'?'0.5':'1');$('moments').innerHTML=moments(p.p,p.x);}
else if(mode==='initial'){text=`μ₀H = ${p.x.toFixed(1)} mT · M/Ms = ${p.y.toFixed(3)} · Δt = ${cfg.dt.toFixed(3)} s`; $('moments').innerHTML=moments(p.p,p.h,cfg.T);}
else if(mode==='rem'){let r=state.data[frame];text=`|H|/H₀ = ${r.x.toFixed(2)} · mIRM = ${r.irm.toFixed(3)} · mDCD = ${r.dcd.toFixed(3)} · ΔM = 0`; $('moments').innerHTML='';}
else if(mode==='time'){text=`t = ${(10**p.x).toExponential(2)} s · IRM/Ms = ${p.y.toFixed(4)} · DCD/Ms = ${curves[1].data[frame].y.toFixed(4)}`;$('moments').innerHTML='';}
else{text=(p.stage?t('Retour après Hr','Return after Hr'):t('Descente depuis la saturation','Descent from saturation'))+` · H/H₀ = ${p.x.toFixed(2)} · M/Ms = ${p.y.toFixed(3)}`;$('moments').innerHTML=heatmap();}
$('readout').textContent=text;$('momentnote').textContent=['zfc','mh','initial'].includes(mode)?t('Les sphères représentent des populations schématiques. L’animation est ralentie. Son temps diffère du temps physique. Le calcul des courbes utilise l’ensemble des particules. Les 24 flèches servent uniquement à l’illustration.','The spheres represent schematic populations. The animation is slowed down. Its time differs from physical time. Curve calculations use the full particle ensemble. The 24 arrows serve only as illustrations.'):'';}
function play(){if(frame>=state.n-1)frame=0;$('play').textContent=t('Pause','Pause');timer=setInterval(()=>{frame++;if(frame>=state.n){frame=state.n-1;stop();}draw();},60);}
function stop(){if(timer)clearInterval(timer);timer=null;if($('play'))$('play').textContent=t('Animer','Play');}
function exportCSV(){let lines=['# NanoBioMat V0.3 pedagogical simulation; not experimental data','# '+JSON.stringify({mode,...cfg}),'curve,x,y'];curves.forEach(c=>c.data.forEach(p=>lines.push(`${c.name},${p.x},${p.y}`)));let url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='NanoBioMat-'+mode+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function resources(){let cards=[['MagnetoPy','https://rinehartgroup.github.io/MagnetoPy/api/zfcfc/',t('Importer, normaliser et tracer des mesures MPMS ZFC/FC et M(H). Ce module ne fournit pas un ajustement universel de K et de la distribution des volumes.','Import, normalize and plot MPMS ZFC/FC and M(H) data. This module does not provide a universal fit of K and volume distributions.')],['Stoner / lmfit','https://stoner-pythoncode.readthedocs.io/en/stable/analysis-fitting.html',t('Outils d’ajustement et modèles, dont Langevin à l’équilibre. Le nom du paquet ne signifie pas qu’il ajuste automatiquement un modèle complet de Stoner–Wohlfarth.','Fitting tools and models, including equilibrium Langevin functions. The package name does not imply automatic fitting of a complete Stoner–Wohlfarth model.')],['FORCsensei','https://github.com/FORCaist/forcsensei',t('Traitement de mesures FORC dans des notebooks Python. Choix du lissage, estimation de la distribution et interprétation demandent une validation sur les données.','FORC measurement processing in Python notebooks. Smoothing choices, distribution estimates and interpretation require data-specific validation.')],['SciPy · least_squares','https://docs.scipy.org/doc/scipy/reference/generated/scipy.optimize.least_squares.html',t('Pour ajuster un modèle physique explicite : pondération des résidus, bornes, identifiabilité de K et V, prise en compte du protocole et estimation des incertitudes.','For fitting an explicit physical model: residual weighting, bounds, K–V identifiability, protocol modelling and uncertainty estimation.')]];
$('resources').innerHTML=`<h2 style="margin-top:32px">${t('Passer des courbes aux données','From curves to data')}</h2><p>${t('Un même outil ne répond pas à tous les protocoles. Ces liens distinguent le traitement des données et l’ajustement d’un modèle.','One tool does not cover every protocol. These links distinguish data processing from fitting a model.')}</p><div class="cards">${cards.map(c=>`<section><h3>${link(c[1],c[0])}</h3><p>${c[2]}</p></section>`).join('')}</div><p>${link('https://lenaiclartigue.github.io/python-chimie/',t('Ressources Python pour la chimie · FR / EN','Python resources for chemistry · FR / EN'))} · <a href="magnetism_reference.py" download>${t('Script Python de référence','Reference Python script')}</a></p><details><summary>${t('Références scientifiques et sources HDR','Scientific references and HDR sources')}</summary><ul><li>E. C. Stoner, E. P. Wohlfarth, <em>Phil. Trans. R. Soc. A</em> <b>1948</b>, <em>240</em>, 599–642. ${link('https://doi.org/10.1098/rsta.1948.0007','DOI: 10.1098/rsta.1948.0007')}</li><li>E. P. Wohlfarth, <em>J. Appl. Phys.</em> <b>1958</b>, <em>29</em>, 595–596. ${link('https://doi.org/10.1063/1.1723232','DOI: 10.1063/1.1723232')}</li><li>F. Tournus, E. Bonet, <em>J. Magn. Magn. Mater.</em> <b>2011</b>, <em>323</em>, 1109–1117. ${link('https://doi.org/10.1016/j.jmmm.2010.11.056','DOI: 10.1016/j.jmmm.2010.11.056')} · ${t('Modélisation ZFC/FC ; consulter également le corrigendum de 2012 (JMMM 324, 656).','ZFC/FC modelling; also consult the 2012 corrigendum.')}</li><li>F. Tournus, A. Tamion, <em>J. Magn. Magn. Mater.</em> <b>2011</b>, <em>323</em>, 1118–1127. ${link('https://doi.org/10.1016/j.jmmm.2010.11.057','DOI: 10.1016/j.jmmm.2010.11.057')}</li><li>A. Hillion et al., <em>Phys. Rev. B</em> <b>2013</b>, <em>88</em>, 094419. ${link('https://doi.org/10.1103/PhysRevB.88.094419','DOI: 10.1103/PhysRevB.88.094419')} · ${t('IRM et distributions d’anisotropie ; équipe de F. Tournus.','IRM and anisotropy distributions; F. Tournus and colleagues.')}</li><li>L. Lartigue et al., <em>J. Am. Chem. Soc.</em> <b>2011</b>, <em>133</em>, 10459–10472. ${link('https://doi.org/10.1021/ja111448t','DOI: 10.1021/ja111448t')} · ${t('Propriétés magnétiques, relaxométrie et hyperthermie des IONPs.','IONP magnetic properties, relaxometry and hyperthermia.')}</li><li>L. Lartigue et al., <em>ACS Nano</em> <b>2012</b>, <em>6</em>, 10935–10949. ${link('https://doi.org/10.1021/nn304477s','DOI: 10.1021/nn304477s')} · ${t('Organisation coopérative des nanoparticules multicœurs.','Cooperative organization in multicore nanoparticles.')}</li><li>${link('https://doi.org/10.1029/2020JB020418','An Automatic Model Selection-Based Machine Learning Framework to Estimate FORC Distributions')} (2020) · ${t('Estimation et lissage des distributions FORC.','FORC distribution estimation and smoothing.')}</li></ul><p>${t('Source de sélection : Presentation HDR(3).pptx, diapositives 6–7 (macrospin), 15–16 (anisotropie et mesures), 20 (effet taille), 25 et 27–28 (interactions), 66 (IRM/DCD et ΔM). La comparaison nanoframboises / nanogrenades est exclue. Les simulations sont nouvelles ; elles ne sont pas présentées comme une reproduction de figures expérimentales de l’HDR ni comme le code de Tournus.','Selection source: Presentation HDR(3).pptx, slides 6–7 (macrospin), 15–16 (anisotropy and measurements), 20 (size effects), 25 and 27–28 (interactions), 66 (IRM/DCD and ΔM). The raspberry/pomegranate comparison is excluded. The simulations are new; they are not presented as reproductions of HDR experimental figures or as Tournus’s code.')}</p></details>`;$('footer').textContent=t('NanoBioMat · Bases théoriques FR / EN. Aucune donnée expérimentale n’est ajustée ici.','NanoBioMat · FR / EN theoretical background. No experimental data are fitted here.');}
$('lang').onclick=()=>{lang=lang==='fr'?'en':'fr';render();};render();
